271	async function generateAITips(answers: Awaited<ReturnType<typeof Questionnaire.runQuestionnaire>>, apiKey: string | null, scan: ScanResult | null) {
272	  if (!apiKey) {
273	    return null;
274	  }
275	  try {
276	    const fetchImpl = await resolveFetchImplementation();
277	    const provider = (Providers.createProvider as unknown as (config: unknown) => any)({
278	      apiKey,
279	      fetch: fetchImpl
280	    });
281	    const context = Documents.buildContextForAITips(answers);
282	    const scanSummary = summarizeScanResult(scan);
283	    const prompt = [
284	      'You are an expert in responsible AI implementation.',
285	      'Provide three actionable recommendations for each documentation artefact (checklist, model card, risk file).',
286	      'Ground the advice in the following feature context and scan summary.'
287	    ].join(' ');
288	
289	    const userContent = [
290	      'AI Feature Context:',
291	      context,
292	      '',
293	      'Scan Summary:',
294	      scanSummary || 'No automated scan results were available.'
295	    ].join('\n');
296	
297	    const response = await provider.chatCompletion({
298	      messages: [
299	        {
300	          role: 'system',
301	          content: prompt
302	        },
303	        {
304	          role: 'user',
305	          content: userContent
306	        }
307	      ],
308	      temperature: 0.3,
309	      maxTokens: 800
310	    });
311	
312	    if (!response?.content) return null;
313	    return String(response.content).trim();
314	  } catch (error) {
315	    log.warn('Unable to generate AI assistance tips. Continuing without them.', {
316	      error: error instanceof Error ? error.message : String(error)
317	    });
318	    return null;
319	  }
320	}
