    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('validates thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    const valid = validateThresholds({ exact_match: 0.5 }, evaluations);
    expect(valid.valid).toBe(true);

    const invalidMetric = validateThresholds({ unknown_metric: 0.5 }, evaluations);
    expect(invalidMetric.valid).toBe(false);
    expect(invalidMetric.errors.length).toBeGreaterThan(0);

    const invalidRange = validateThresholds({ exact_match: 1.5 }, evaluations);
    expect(invalidRange.valid).toBe(false);
  });

  it('evaluates thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const results = evaluateThresholds({ exact_match: 0.9, toxicity: 0.5 }, evaluations);
    expect(results).toHaveLength(2);
    expect(results.some((r) => r.metric === 'exact_match')).toBe(true);
    expect(results.some((r) => r.metric === 'toxicity')).toBe(true);
  });

  it('includes thresholds in generated report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.9 }
    });

    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(1);
    expect(report.thresholds[0].metric).toBe('exact_match');
    expect(report.thresholds[0].passed).toBe(true);
  });

  it('fails threshold when score is null', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: []
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { length_variance: 0.5 }
    });

    const lengthVariance = report.thresholds.find((t) => t.metric === 'length_variance');
    expect(lengthVariance.score).toBe(null);
    expect(lengthVariance.passed).toBe(false);
    expect(report.passed).toBe(false);
  });

  it('report passes when no thresholds are set', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json'
    });

    expect(report.thresholds).toBeUndefined();
    expect(report.passed).toBeUndefined();
  });

  it('throws on invalid thresholds in generateReport', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    expect(() => {
      generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        thresholds: { unknown_metric: 0.5 }
      });
    }).toThrow();
  });
});

