### 2.2 Add validateThresholdsAgainstEvaluations Function
```javascript
export function validateThresholdsAgainstEvaluations(
  evaluations,
  thresholds
) {
  // Input validation: thresholds must be array or empty
  const thresholdList = Array.isArray(thresholds) ? thresholds : [];
  if (thresholdList.length === 0) {
    return { results: [], passed: true };
  }

  // Map evaluations to metric ID for quick lookup
  const metricsMap = new Map(
    evaluations.map((m) => [m.id, m])
  );

  // Validate each threshold
  const results = thresholdList.map((threshold) => {
    const metric = metricsMap.get(threshold.metricId);

    if (!metric) {
      return {
        metricId: threshold.metricId,
        minScore: threshold.minScore,
        actualScore: null,
        passed: false,
        reason: `Metric not found: ${threshold.metricId}`
      };
    }

    // Check if metric has a score (null score means no valid data)
    if (metric.score === null || metric.score === undefined) {
      return {
        metricId: threshold.metricId,
        minScore: threshold.minScore,
        actualScore: null,
        passed: false,
        reason: 'Metric has no valid score (insufficient data)'
      };
    }

    const passed = metric.score >= threshold.minScore;
    return {
      metricId: threshold.metricId,
      minScore: threshold.minScore,
      actualScore: metric.score,
      passed,
      reason: passed
        ? `Score ${metric.score} meets threshold ${threshold.minScore}`
        : `Score ${metric.score} below threshold ${threshold.minScore}`
    };
  });

  // Report passes only if all thresholds pass
  const passed = results.every((r) => r.passed);

  return { results, passed };
}
```

**Edge case handling:**
- Metric not in evaluations → passed=false with reason
- Score is null (e.g., exact_match without references) → passed=false with reason
- Custom metrics → look up by ID same way
- Empty thresholds array → results=[], passed=true (no requirements)

