export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = []  // NEW: optional parameter
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  // NEW: Validate thresholds against evaluations
  const thresholdValidation = validateThresholdsAgainstEvaluations(
    evaluations,
    thresholds
  );

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  // NEW: Add threshold fields if thresholds were provided
  if (Array.isArray(thresholds) && thresholds.length > 0) {
    report.passed = thresholdValidation.passed;
    report.thresholds = thresholdValidation.results;
  }

  return report;
}
